function status(msg,sticky=false){$('#status').textContent=msg;$('#status').style.display='block';clearTimeout(status.t);if(!sticky)status.t=setTimeout(()=>$('#status').style.display='none',4200)}
function save(){try{localStorage.setItem('atlas-studio-v1',JSON.stringify(state));$('#saved').textContent='已自動儲存'}catch{status('瀏覽器儲存空間不足，請匯出備份。')}}
