function key(n){const raw=n.feature.properties['ISO3166-1-Alpha-3'];const idIso=n.level===0&&!/^[A-Z]{3}$/.test(raw||'')?n.feature.properties.name:n.iso;return idIso+':'+n.level+':'+(n.feature.properties.shapeID||n.feature.properties.name)}
function rootNodes(){nodes={};world.features.forEach(f=>{let iso=f.properties['ISO3166-1-Alpha-3'];if(!iso||iso==='-99')iso=({France:'FRA',Norway:'NOR'})[f.properties.name]||f.properties.name;const ownedFeature=isolateCountryFeature(f,iso,taiwanProtection);if(!ownedFeature)return;let n={iso,level:0,name:f.properties.name,feature:ownedFeature,parent:null,children:[]};n.id=key(n);nodes[n.id]=n})}
