function select(n){selected=n;const r=$('#region');r.querySelector('span').textContent=n.level===0?'國家':`${n.iso} / ADM${n.level}`;r.querySelector('b').textContent=n.name;r.querySelector('small').textContent=n.level===0?'雙擊拆分；單擊套用標記':`${n.canonical||'行政區'} · ${n.year||''}`;$('#split').hidden=!!n.children.length;$('#merge').hidden=!n.parent&&!n.children.length}
function labelFor(k){if(state.labels[k])return Promise.resolve(true);return new Promise(resolve=>{const d=$('#labelDialog');$('#labelInput').value='';d.showModal();$('#labelInput').focus();$('#labelForm').onsubmit=e=>{e.preventDefault();const v=$('#labelInput').value.trim();if(!v)return;state.labels[k]=v;d.close();resolve(true)};$('#cancelLabel').onclick=()=>d.close();d.oncancel=()=>{};d.onclose=()=>resolve(!!state.labels[k])})}
async function apply(n){if(busy||mode==='pan')return;busy=true;try{const k=mode==='color'?'color:'+color:'icon:'+icon;const before=JSON.stringify(state);if(mode==='icon'&&!await labelFor(k))return;history.push(before);if(history.length>25)history.shift();if(mode==='erase'){state.marks[n.id]={};for(const child of descendants(n))delete state.marks[child.id]}else state.marks[n.id]={...mark(n),[mode]:mode==='color'?color:icon};save();render()}finally{busy=false}}
function descendants(n){return n.children.filter(id=>nodes[id]?.iso===n.iso).flatMap(id=>[nodes[id],...descendants(nodes[id])])}
async function getLevel(iso,level){if(iso==='TWN'&&level===1){const source=[...boundarySources.values()].find(s=>s.iso==='TWN');return {data:taiwanData,meta:{...source.metadata,boundaryCanonical:'縣／市'}}}const k=iso+level;if(cache.has(k))return cache.get(k);const promise=(async()=>{const res=await fetch('https://www.geoboundaries.org/api/current/gbOpen/'+iso+'/ADM'+level+'/',{signal:AbortSignal.timeout(25000)});if(res.status===404)return null;if(!res.ok)throw Error('行政區服務暫時無法連線');let meta=await res.json();if(Array.isArray(meta))meta=meta[0];if(!meta?.simplifiedGeometryGeoJSON)return null;const source=registerBoundarySource(meta,iso,level);const dataRes=await fetch(source.download_url,{signal:AbortSignal.timeout(60000)});if(!dataRes.ok)throw Error('邊界資料下載失敗');return {data:await dataRes.json(),meta}})();cache.set(k,promise);try{return await promise}catch(e){cache.delete(k);throw e}}
const terminalTypes=/county|counties|district|municipalit|commune|independent city|prefecture/i;
async function split(n,restoring=false){if(!restoring&&(busy||n.children.length))return;if(!restoring)busy=true;try{if((n.iso==='TWN'&&n.level>=1)||n.level>=5||(n.level>=2&&terminalTypes.test(n.canonical||'')&&!/government|regional/i.test(n.canonical||''))){if(!restoring)status('此區已達縣市層級。');return}if(!/^[A-Z]{3}$/.test(n.iso)){status('此地區尚無可用的行政区代碼。');return}if(!restoring)status(`正在載入 ${n.name} 的下一層行政區…`,true);const next=await getLevel(n.iso,n.level+1);if(!next){if(!restoring)status('資料來源尚未提供更細的行政區；保留目前範圍。');return}const children=next.data.features.map(f=>isolateCountryFeature(f,n.iso,taiwanProtection)).filter(Boolean).filter(f=>{if(n.level===0)return true;try{return turf.booleanPointInPolygon(turf.pointOnFeature(f),n.feature)}catch{return false}});if(children.length<=1){if(!restoring)status('沒有可拆分的下一層行政區。');return}if(!restoring)checkpoint();children.forEach(f=>{const c={iso:n.iso,level:n.level+1,name:f.properties.shapeName||f.properties.name||'未命名行政區',feature:f,parent:n.id,children:[],canonical:next.meta.boundaryCanonical,year:next.meta.boundaryYearRepresented};c.id=key(c);nodes[c.id]=c;n.children.push(c.id)});if(!state.splits.includes(n.id))state.splits.push(n.id);if(!restoring){save();render();select(n);map.fitBounds(n.layer.getBounds(),{padding:[70,70],maxZoom:9});status(`已拆分為 ${children.length} 個${next.meta.boundaryCanonical}，可分別上色。`)}}catch(e){if(restoring)throw e;status(`載入失敗：${e.message}。可再次雙擊重試。`)}finally{if(!restoring)busy=false}}
function merge(){if(busy||!selected)return;const n=selected.children.length?selected:nodes[selected.parent];if(!n||n.iso!==selected.iso||!confirm('合併會移除下層的獨立標記，使用此區原本的標記。繼續？'))return;checkpoint();const ids=descendants(n).map(c=>c.id);state.splits=state.splits.filter(id=>id!==n.id&&!ids.includes(id));ids.forEach(id=>{delete state.marks[id];delete nodes[id]});n.children=[];save();render();select(n)}
function renderLegend(){const box=$('#legend-items');box.replaceChildren();const used=new Set();leaves().forEach(n=>{const m=mark(n);if(m.color)used.add('color:'+m.color);if(m.icon)used.add('icon:'+m.icon)});if(!used.size){const p=document.createElement('p');p.textContent='著色直接套用；圖示首次使用時加上說明。點擊圖例可修改文字。';box.append(p)}used.forEach(k=>{const row=document.createElement('div');row.className='legend-row';row.title='點擊修改說明';const dot=document.createElement('span');if(k.startsWith('color:')){dot.className='dot';dot.style.background=k.slice(6)}else dot.textContent=k.slice(5);const text=document.createElement('span');text.textContent=state.labels[k]||(k.startsWith('color:')?'色彩 '+k.slice(6):'未命名');row.append(dot,text);row.onclick=()=>{const value=prompt('修改圖例說明',state.labels[k]||'');if(value?.trim()){checkpoint();state.labels[k]=value.trim().slice(0,80);save();renderLegend()}};box.append(row)})}
async function restore(s){const previous=state;busy=true;status('正在還原地圖與行政區…',true);try{state=s;rootNodes();for(const id of [...s.splits]){const n=nodes[id];if(!n){if(id.startsWith('CHN:')){state.splits=state.splits.filter(x=>x!==id);delete state.marks[id];continue}throw Error('找不到已儲存的行政區')}await split(n,true);if(!n.children.length)throw Error('部分行政區已無法取得')}selected=null;render();save();status('地圖已還原')}catch(e){state=previous;rootNodes();for(const id of previous.splits){if(nodes[id])try{await split(nodes[id],true)}catch{}}render();status('還原未完成：'+e.message+'。原有編輯已保留。')}finally{busy=false}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b))});
function drawPalette(){const p=$('#palette');p.replaceChildren();colors.forEach(c=>{const b=document.createElement('button');b.className='swatch'+(c===color?' active':'');b.style.background=c;b.title=c;b.setAttribute('aria-label','選擇色彩 '+c);b.onclick=()=>{color=c;drawPalette();$('[data-mode=color]').click()};p.append(b)})}drawPalette();$('#customColor').oninput=e=>{color=e.target.value;drawPalette();$('[data-mode=color]').click()};['★','●','⚑','♥','✈','◆'].forEach(i=>{const b=document.createElement('button');b.textContent=i;b.title='使用 '+i;b.className=i===icon?'active':'';b.onclick=()=>{icon=i;$('#icons').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));$('[data-mode=icon]').click()};$('#icons').append(b)});
$('#split').onclick=()=>selected&&split(selected);$('#merge').onclick=merge;$('#home').onclick=()=>map.setView([24,12],2);$('#undo').onclick=()=>{if(!busy&&history.length)restore(JSON.parse(history.pop()))};$('#reset').onclick=()=>{if(!busy&&confirm('清除所有色彩與圖示？行政區拆分將保留。')){checkpoint();state.marks={};save();render()}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='atlas-map.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#import').onclick=()=>!busy&&$('#file').click();$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10000000)throw Error('檔案過大');const s=JSON.parse(await f.text());if(s.version!==1||!s.marks||!s.labels||!Array.isArray(s.splits)||s.splits.some(x=>typeof x!=='string')||Object.values(s.labels).some(x=>typeof x!=='string')||Object.values(s.marks).some(m=>!m||typeof m!=='object'||(m.color&&!/^#[0-9a-f]{6}$/i.test(m.color))||(m.icon&&!['★','●','⚑','♥','✈','◆'].includes(m.icon))))throw Error('不是有效的 Atlas 地圖檔');if(s.merged&&(typeof s.merged!=='object'||Array.isArray(s.merged)||Object.values(s.merged).some(v=>!Array.isArray(v)||v.some(id=>typeof id!=='string'))))throw Error('合併資料格式無效');checkpoint();await restore({marks:s.marks,labels:s.labels,splits:s.splits,merged:s.merged||{}})}catch(e){status('無法匯入：'+e.message)}e.target.value=''};
async function init(){try{status('正在載入世界地圖…',true);const [r,t]=await Promise.all([fetch('world.geojson'),fetch('taiwan.geojson')]);if(!r.ok||!t.ok)throw Error('世界國界或台灣保護邊界讀取失敗');[world,taiwanData]=await Promise.all([r.json(),t.json()]);await initializeDataLicensing();taiwanProtection=[...world.features.filter(f=>f.properties['ISO3166-1-Alpha-3']==='TWN'),...taiwanData.features];rootNodes();render();let stored;try{stored=JSON.parse(localStorage.getItem('atlas-studio-v1'))}catch{}if(stored){state=stored;await restore(stored);}else status('地圖已就緒：單擊著色，雙擊拆分。')}catch(e){status('無法載入地圖：'+e.message+'。請重新整理。',true)}}
const renderBase=render;let initialView=true;render=function(){renderBase();for(const n of leaves())n.layer.eachLayer(l=>{const el=l.getElement();if(el){el.setAttribute('aria-label',n.name);el.setAttribute('role','button');el.setAttribute('tabindex','0');el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();select(n);e.shiftKey?split(n):apply(n)}}}});if(initialView){initialView=false;homeView()}};function homeView(){map.fitBounds([[-60,-180],[80,180]],{paddingTopLeft:[20,60],paddingBottomRight:[20,110]})}$('#home').onclick=homeView;










